const client =$('Start').first().json.client_id ;

const rawReportDate = $('Start').first().json.reportDate_firstItem;
const reportDate = String(rawReportDate).substring(0, 10);

const isBackfill = !!$('Start').first().json.isBackfill_firstItem;

const lineJson = $('HTTP Line Stats1').item.json;
const lineOk = !!(lineJson && Array.isArray(lineJson.data));

let emailsSent = lineOk ? 0 : null;
let responseCount = lineOk ? 0 : null;

if (lineOk) {
  for (const item of lineJson.data) {
    const de = (item.dates || []).find(d => d[0] === reportDate);
    const val = de ? (de[1] || 0) : 0;

    if (item.label === 'Sent') {
      emailsSent = val;
    } else if (item.label === 'Replied') {
      responseCount = val;
    }
  }
}

const bounceJson = $('HTTP Stats Bounce1').item.json;
const bounceOk = !!(bounceJson && bounceJson.data);
const bounceCount = bounceOk ? (bounceJson.data.bounced || 0) : null;

const senderJson = $('HTTP Sender Emails1').item.json;
const inboxesCount =
  senderJson &&
  senderJson.meta &&
  typeof senderJson.meta.total === 'number'
    ? senderJson.meta.total
    : null;

const leadsJson = $('HTTP Leads1').item.json;
const prospectsTotal =
  leadsJson &&
  leadsJson.meta &&
  typeof leadsJson.meta.total === 'number'
    ? leadsJson.meta.total
    : null;

const humanJson = $('HTTP Human Replies1').item.json;
const humanRepliesTotal =
  humanJson &&
  humanJson.meta &&
  typeof humanJson.meta.total === 'number'
    ? humanJson.meta.total
    : null;

const autoJson = $('HTTP Automated Replies1').item.json;
const automatedRepliesTotal =
  autoJson &&
  autoJson.meta &&
  typeof autoJson.meta.total === 'number'
    ? autoJson.meta.total
    : null;

const prevRow = $('Get Yesterday Totals1').item.json;

const prevHumanTotal = prevRow ? (Number(prevRow.prev_human_total) || 0) : 0;
const prevAutoTotal = prevRow ? (Number(prevRow.prev_auto_total) || 0) : 0;
const prevProspectsTotal = prevRow ? (Number(prevRow.prev_prospects_total) || 0) : 0;
const prevOooTotal = prevRow ? (Number(prevRow.prev_ooo_total) || 0) : 0;
const prevReportDate = prevRow ? String(prevRow.prev_report_date || '').substring(0, 10) : '';

const humanRepliesCount =
  humanRepliesTotal === null
    ? null
    : Math.max(humanRepliesTotal - prevHumanTotal, 0);

const automatedRepliesCount =
  automatedRepliesTotal === null
    ? null
    : Math.max(automatedRepliesTotal - prevAutoTotal, 0);
const oooCount =
  automatedRepliesTotal === null
    ? null
    : Math.max(automatedRepliesTotal - prevOooTotal, 0);

const todayMonth = reportDate.substring(0, 7);
const prevMonth = prevReportDate ? prevReportDate.substring(0, 7) : '';

let prospectsCount;

if (prospectsTotal === null) {
  prospectsCount = null;
} else if (!prevMonth || prevMonth !== todayMonth) {
  prospectsCount = prospectsTotal;
} else {
  prospectsCount = Math.max(prospectsTotal - prevProspectsTotal, 0);
}

const sumSched = (j) => {
  if (!j || !Array.isArray(j.data)) return null;

  return j.data.reduce((s, it) => {
    return s + (Number(it.emails_being_sent) || 0);
  }, 0);
};

const scheduleToday = sumSched($('HTTP Schedule Today1').item.json);
const scheduleTomorrow = sumSched($('HTTP Schedule Tomorrow1').item.json);
const scheduleDayAfter = sumSched($('HTTP Schedule DayAfter1').item.json);

// Use UTC noon to avoid timezone/date boundary issues.
const dateObj = new Date(reportDate + 'T12:00:00Z');

const year = dateObj.getUTCFullYear();
const monthNumber = dateObj.getUTCMonth() + 1;

const getISOWeek = (d) => {
  const dt = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));

  dt.setUTCDate(dt.getUTCDate() + 4 - (dt.getUTCDay() || 7));

  const y0 = new Date(Date.UTC(dt.getUTCFullYear(), 0, 1));

  return Math.ceil((((dt - y0) / 86400000) + 1) / 7);
};

const weekNumber = getISOWeek(dateObj);

const fmt = (v) => {
  return v === null || v === undefined ? 'NULL' : String(v);
};

const fmtStr = (v) => {
  return "'" + String(v).replace(/'/g, "''") + "'";
};

const cols = [
  'client_id',
  'report_date',
  'emails_sent',
  'response_count',
  'bounce_count',
  'inboxes_count',
  'prospects_count',
  'prospects_total',
  'human_replies_count',
  'human_replies_total',
  'automated_replies_count',
  'automated_replies_total',
  'schedule_today',
  'schedule_tomorrow',
  'schedule_day_after',
  'negative_count',
  'ooo_count',
  'ooo_count_total',
  'mql_count',
  'me_count',
  'won_count',
  'prospects_in_base',
  'week_number',
  'month_number',
  'year',
].join(', ');

const valsArr = [
  fmtStr(client),
  fmtStr(reportDate) + '::date',
  fmt(emailsSent),
  fmt(responseCount),
  fmt(bounceCount),
  fmt(inboxesCount),
  fmt(prospectsCount),
  fmt(prospectsTotal),
  fmt(humanRepliesCount),
  fmt(humanRepliesTotal),
  fmt(automatedRepliesCount),   
  fmt(automatedRepliesTotal),   
  fmt(scheduleToday),
  fmt(scheduleTomorrow),
  fmt(scheduleDayAfter),
  '0',                          
  fmt(oooCount),               
  fmt(automatedRepliesTotal),   
  '0',                          
  '0',
  '0',
  '0',
  fmt(weekNumber),
  fmt(monthNumber),
  fmt(year),
];


const vals = '(' + valsArr.join(', ') + ')';

const updateColsBackfill = [
  'emails_sent',
  'response_count',
  'bounce_count',
  'inboxes_count',
  'prospects_count',
  'prospects_total',
  'human_replies_count',
  'human_replies_total',
  'automated_replies_count',
  'automated_replies_total',
  'schedule_today',
  'schedule_tomorrow',
  'schedule_day_after',
  'ooo_count',
  'ooo_count_total',
];

const updateColsNormal = [
  'emails_sent',
  'response_count',
  'bounce_count',
  'inboxes_count',
  'prospects_count',
  'prospects_total',
  'human_replies_count',
  'human_replies_total',
  'automated_replies_count',
  'automated_replies_total',
  'schedule_today',
  'schedule_tomorrow',
  'schedule_day_after',
  'ooo_count',
  'ooo_count_total',
  'week_number',
  'month_number',
  'year',
];

let updateClause = '';

if (isBackfill) {
  updateClause = updateColsBackfill
    .map(c => `${c} = COALESCE(EXCLUDED.${c}, daily_stats.${c})`)
    .join(', ');

  updateClause += ', week_number = EXCLUDED.week_number';
  updateClause += ', month_number = EXCLUDED.month_number';
  updateClause += ', year = EXCLUDED.year';
} else {
  updateClause = updateColsNormal
    .map(c => `${c} = EXCLUDED.${c}`)
    .join(', ');
}

const sql =
  'INSERT INTO daily_stats (' +
  cols +
  ') VALUES ' +
  vals +
  ' ON CONFLICT (client_id, report_date) DO UPDATE SET ' +
  updateClause +
  ' RETURNING id, client_id, report_date::text AS report_date';

return [
  {
    json: {
      sql,
      client_name: client,
      report_date: reportDate,
      is_backfill: isBackfill,
      emails_sent: emailsSent,
      response_count: responseCount,
      bounce_count: bounceCount,
    },
  },
];
